import 'jest';
import { parseBool } from '../../src';

describe('parseBoolean()', () => {
    test('will error if value is null', () => {
        expect(() => parseBool(null)).toThrow();
    });

    test('will error if value is undefined', () => {
        expect(() => parseBool(void 0)).toThrow();
    });

    test('will error if value is not boolean', () => {
        expect(() => parseBool('test string')).toThrow();
    });

    test('will parse true values', () => {
        expect(parseBool('true')).toEqual(true);
        expect(parseBool('True')).toEqual(true);
        expect(parseBool('TRUE')).toEqual(true);
        expect(parseBool('TrUe')).toEqual(true);
    });

    test('will parse false values', () => {
        expect(parseBool('false')).toEqual(false);
        expect(parseBool('False')).toEqual(false);
        expect(parseBool('FALSE')).toEqual(false);
        expect(parseBool('FaLsE')).toEqual(false);
    });
});